 document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(overlay)closeModal();else if(playing)openPause();return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||overlay||!playing)return;const k=e.key.toLowerCase();keys.add(k);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='e')openInventory();if(k==='f')cycleCamera();if(k==='g')useDoor();if(k==='r')rotateBlock();if(k===' ')jump();if(k==='z'&&(e.ctrlKey||e.metaKey)){e.preventDefault();undo();}if(/^[1-9]$/.test(k)){const m=MATERIALS.filter(m=>m.group===category)[Number(k)-1];if(m)selectMaterial(m.id);}});
 document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();stick={x:0,y:0};if(playing&&!overlay)openPause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(playing)saveWorld(true);if(playing&&!overlay)openPause();}});window.addEventListener('pagehide',()=>{if(playing)saveWorld(true);});
 const canvas=$('#world');canvas.addEventListener('contextmenu',e=>e.preventDefault());
