function groundHeight(x,z){let top=0;for(const b of world.blocks){if(['wire','lamp','solar','plant','flower','switch','tv'].includes(b.type))continue;if(Math.abs(b.x-x)<.7&&Math.abs(b.z-z)<.7&&b.y+1<=world.player.y+.75)top=Math.max(top,b.y+1);}return top;}
function blocked(x,z){return world.blocks.some(b=>!(b.type==='door'&&b.open)&&!['wire','lamp','solar','plant','flower','switch','path'].includes(b.type)&&Math.abs(b.x-x)<.67&&Math.abs(b.z-z)<.67&&b.y<world.player.y+1.6&&b.y+1>world.player.y+.28);}
function jump(){if(playing&&!overlay&&world.player.y<=groundHeight(world.player.x,world.player.z)+.04)velocityY=5.8;}
function movePlayer(dt){let f=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-stick.y,r=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stick.x;const n=Math.hypot(f,r),p=world.player;if(n>0){f/=Math.max(1,n);r/=Math.max(1,n);const speed=(keys.has('shift')?6:3.7)*dt,dx=(-Math.sin(renderer.yaw)*f+Math.cos(renderer.yaw)*r)*speed,dz=(-Math.cos(renderer.yaw)*f-Math.sin(renderer.yaw)*r)*speed;const X=Math.max(-13,Math.min(13,p.x+dx)),Z=Math.max(-11,Math.min(11,p.z+dz));if(!blocked(X,p.z))p.x=X;if(!blocked(p.x,Z))p.z=Z;p.yaw=Math.atan2(dx,dz);dirty=true;}
 velocityY-=15*dt;p.y+=velocityY*dt;const ground=groundHeight(p.x,p.z);if(p.y<ground){p.y=ground;velocityY=0;}return n>.05;
}
